items.solution:
def withdraw(balance, amount):
    if amount > balance:
        raise ValueError("insufficient funds")
    return balance - amount

def safe_div(a, b, log):
    try:
        r = a / b
    except ZeroDivisionError:
        log.append("div0")
        return None
    else:
        log.append("ok")
        return r
    finally:
        log.append("done")

